#!/usr/bin/env python3
"""Static contract tests for systemd units generated by the installer.
These checks do not boot a VM; tests/systemd/boot.sh is a separate QEMU runner.
"""
import os
from pathlib import Path
import subprocess
import unittest

REPO_ROOT = Path(__file__).resolve().parent.parent


class TestSystemdRunner(unittest.TestCase):

    def test_boot_script_executable(self):
        """tests/systemd/boot.sh must exist and be executable."""
        boot_sh = REPO_ROOT / "tests" / "systemd" / "boot.sh"
        self.assertTrue(boot_sh.is_file())
        self.assertTrue(os.access(boot_sh, os.X_OK))

    def test_systemd_unit_generation_and_ordering(self):
        """Inspect actual unit templates emitted by configure_panel_systemd()."""
        source = (REPO_ROOT / "modules" / "panel.sh").read_text()
        self.assertIn("Before=gowave.service gowave-node.service", source)
        self.assertIn("ExecStart=/usr/local/sbin/gowave-auto.sh recover --boot-files", source)
        self.assertIn("After=gowave.service", source)
        self.assertIn("ExecStart=/usr/local/sbin/gowave-auto.sh recover --boot-provision", source)

    def test_bbr_load_service_ordering(self):
        """Inspect the actual BBR unit template emitted by configure_bbr_and_mtu()."""
        source = (REPO_ROOT / "modules" / "security.sh").read_text()
        self.assertIn("Before=systemd-sysctl.service", source)
        self.assertIn("ExecStart=-/sbin/modprobe tcp_bbr", source)
        self.assertIn("ExecStart=-/sbin/sysctl -w net.ipv4.tcp_congestion_control=bbr", source)


if __name__ == "__main__":
    unittest.main()
